import pandas as pd
from pymatgen.io.vasp import Poscar
from pymatgen.analysis.structure_matcher import StructureMatcher
x=pd.read_csv('/work/nlo_pool.csv'); ss={r.candidate_id:Poscar.from_str(r.poscar).structure for _,r in x.iterrows()}
sm=StructureMatcher(ltol=.3,stol=.3,angle_tol=10,primitive_cell=True,scale=True,attempt_supercell=True)
for grp in [['c001','c002','c003','c004'],list(f'c{i:03}' for i in range(8,14)),list(f'c{i:03}' for i in range(14,20)),list(f'c{i:03}' for i in range(24,30)),list(f'c{i:03}' for i in range(31,37)),list(f'c{i:03}' for i in range(40,46)),['c050','c051','c052'],['c076','c077','c078'],['c084','c085'],list(f'c{i:03}' for i in range(94,100))]:
 print('\n',grp)
 for i,a in enumerate(grp):
  for b in grp[i+1:]:
   if sm.fit(ss[a],ss[b]):
    print(a,b,sm.get_rms_dist(ss[a],ss[b]))
