import pandas as pd,numpy as np
from pymatgen.io.vasp import Poscar
x=pd.read_csv('nlo_pool.csv')
for cid in [f'c{i:03}' for i in range(40,46)]:
 r=x[x.candidate_id==cid].iloc[0];s=Poscar.from_str(r.poscar).structure; M=np.zeros((3,3));n=0
 for st in s:
  if st.specie.symbol=='B':
   for nn in s.get_neighbors(st,2.1):
    if nn.specie.symbol=='S':
     u=(nn.coords-st.coords)/nn.nn_distance;M+=np.outer(u,u);n+=1
 ev=np.linalg.eigvalsh(M/n); q=ev[-1]-ev[0];vol=s.volume/len(s)
 print(cid,'q',q,'vol/atom',vol,'D',q/vol,'evals',ev)
